/* The builder prepends self.SITE_BUILD with the exact output hashes. */
"use strict";

const build = self.SITE_BUILD;
const scope = new URL(self.registration.scope);
const namespace = "school-offline-v1:" + encodeURIComponent(scope.href) + ":";
if (!build || !/^[a-f0-9]{64}$/.test(build.version) || !Array.isArray(build.files) || !build.files.length) {
  throw new Error("Invalid offline build");
}
const versionPrefix = namespace + build.version + ":";
const readyURL = new URL(".offline-ready/" + build.version, scope).href;
const files = new Map();
for (const file of build.files) {
  const url = new URL(file.url, scope);
  if (!file.url || file.url.startsWith("/") || url.origin !== scope.origin ||
      !url.pathname.startsWith(scope.pathname) || url.search || url.hash ||
      !/^[a-f0-9]{64}$/.test(file.sha256) || files.has(url.href)) {
    throw new Error("Invalid offline file");
  }
  files.set(url.href, file.sha256);
}

async function findReadyCache() {
  const names = (await caches.keys()).filter(name => name.startsWith(versionPrefix)).reverse();
  for (const name of names) {
    const cache = await caches.open(name);
    const marker = await cache.match(readyURL);
    if (marker && await marker.text() === build.version) return { name, cache };
  }
  return null;
}

let readyCache;
function getReadyCache() {
  if (readyCache) return readyCache;
  // A status request can arrive while installation is still downloading.
  // Never memoize "not ready" across the final ready-marker write.
  return findReadyCache().then(ready => {
    if (ready) readyCache = Promise.resolve(ready);
    return ready;
  });
}

async function reusableCaches() {
  const ready = [];
  const names = (await caches.keys()).filter(name => name.startsWith(namespace)).reverse();
  for (const name of names) {
    const version = name.slice(namespace.length).split(":")[0];
    if (!/^[a-f0-9]{64}$/.test(version)) continue;
    const cache = await caches.open(name);
    const marker = await cache.match(new URL(".offline-ready/" + version, scope).href);
    if (marker && await marker.text() === version) ready.push(cache);
  }
  return ready;
}

async function matchesHash(response, expected) {
  if (!response || !response.ok) return false;
  const bytes = await response.clone().arrayBuffer();
  const digest = new Uint8Array(await crypto.subtle.digest("SHA-256", bytes));
  const actual = [...digest].map(byte => byte.toString(16).padStart(2, "0")).join("");
  return actual === expected;
}

async function reuseResponse(previous, url, expected) {
  for (const cache of previous) {
    // Recheck actual bytes against the NEW build, including when migrating
    // from workers that stored no per-file metadata. An evicted or damaged
    // entry is a cache miss; it must be downloaded and verified again.
    try {
      const response = await cache.match(url);
      if (await matchesHash(response, expected)) return response;
    } catch {
      // A failed cache read must not prevent recovery from the network.
    }
  }
  return null;
}

async function installSnapshot() {
  if (await findReadyCache()) return;
  const previous = await reusableCaches();
  // Each attempt owns its cache: a failed duplicate install cannot erase a ready one.
  const name = versionPrefix + crypto.randomUUID();
  let failure;
  try {
    const cache = await caches.open(name);
    const entries = [...files];
    let next = 0;
    async function download() {
      while (!failure && next < entries.length) {
        const [url, expected] = entries[next++];
        try {
          let response = await reuseResponse(previous, url, expected);
          if (!response) {
            const request = new Request(url, {
              method: "GET", cache: "no-store", credentials: "same-origin",
              mode: "same-origin", redirect: "error"
            });
            response = await fetch(request);
            if (!response.ok) throw new Error("Offline download failed: " + url);
            if (!await matchesHash(response, expected)) throw new Error("Offline hash mismatch: " + url);
          }
          await cache.put(url, response);
        } catch (error) {
          failure = error;
        }
      }
    }
    // Await all in-flight writes before deleting an unsuccessful attempt.
    await Promise.all(Array.from({ length: Math.min(5, entries.length) }, download));
    if (failure) throw failure;
    await cache.put(readyURL, new Response(build.version, {
      headers: { "Content-Type": "text/plain; charset=utf-8" }
    }));
    readyCache = Promise.resolve({ name, cache });
  } catch (error) {
    await caches.delete(name);
    throw error;
  }
}

self.addEventListener("install", event => event.waitUntil((async () => {
  await installSnapshot();
  // Take over only after every byte has passed verification. Existing pages
  // remain open; the page UI decides when the user wants to reload the text.
  await self.skipWaiting();
})()));
self.addEventListener("activate", event => event.waitUntil((async () => {
  const ready = await getReadyCache();
  if (!ready) throw new Error("No complete offline snapshot");
  await Promise.all((await caches.keys()).map(async name => {
    if (!name.startsWith(namespace) || name === ready.name) return;
    const version = name.slice(namespace.length).split(":")[0];
    if (!/^[a-f0-9]{64}$/.test(version)) return;
    const cache = await caches.open(name);
    const marker = await cache.match(new URL(".offline-ready/" + version, scope).href);
    // A concurrently installing worker owns its unfinished cache. Deleting it
    // would detach its Cache object while its downloads are still writing.
    if (marker && await marker.text() === version) await caches.delete(name);
  }));
  await self.clients.claim();
})()));

self.addEventListener("message", event => {
  const type = event.data && event.data.type;
  if (!["GET_STATUS", "GET_VERSION", "SKIP_WAITING"].includes(type)) return;
  event.waitUntil((async () => {
    const ready = await getReadyCache();
    if (type === "SKIP_WAITING" && ready) await self.skipWaiting();
    const port = event.ports && event.ports[0];
    if (port) port.postMessage({ version: build.version, ready: Boolean(ready) });
  })());
});

function unavailable() {
  return new Response("Offline copy unavailable", {
    status: 503, headers: { "Content-Type": "text/plain; charset=utf-8" }
  });
}

async function freshNetwork(request, html) {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 5000);
  try {
    return await fetch(new Request(request, {
      cache: html ? "no-store" : "no-cache", signal: controller.signal
    }));
  } finally {
    clearTimeout(timeout);
  }
}

async function markOfflineHTML(cached) {
  const text = await cached.clone().text();
  if (!/text\/html/i.test(cached.headers.get("Content-Type") || "") &&
      !/<(?:head|html)\b|<!doctype\s+html/i.test(text)) return cached;
  const marker = '<meta name="school-offline" content="true">';
  const marked = /<head\b[^>]*>/i.test(text)
    ? text.replace(/<head\b[^>]*>/i, head => head + marker)
    : marker + text;
  const headers = new Headers(cached.headers);
  // The synthetic body contains decoded text, not the original wire bytes.
  headers.delete("Content-Length");
  headers.delete("Content-Encoding");
  return new Response(marked, {
    status: cached.status, statusText: cached.statusText, headers
  });
}

self.addEventListener("fetch", event => {
  if (event.request.method !== "GET") return;
  const url = new URL(event.request.url);
  if (url.origin !== scope.origin || !url.pathname.startsWith(scope.pathname)) return;
  url.search = "";
  url.hash = "";
  if (url.pathname.endsWith("/")) url.pathname += "index.html";
  const html = event.request.mode === "navigate" || url.pathname.endsWith(".html");
  event.respondWith((async () => {
    try {
      const response = await freshNetwork(event.request, html);
      // Do not hide intentional removals (404/410) behind an old saved page.
      if (response.status < 500) return response;
    } catch {
      // No connection, or a slow connection: use only the verified snapshot.
    }
    // Unknown URLs never get another page as a substitute.
    if (!files.has(url.href)) return unavailable();
    const ready = await getReadyCache();
    const cached = ready && await ready.cache.match(url.href);
    if (cached) return html ? markOfflineHTML(cached) : cached;
    // Runtime network responses never mutate the verified offline snapshot.
    return unavailable();
  })());
});
